insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:camille-martin'), 'camille-martin', 'Camille Martin', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:party:renaissance-citoyenne'), 'Ancienne haute fonctionnaire et élue locale, Camille Martin défend une ligne réformiste centriste : équilibre des finances publiques, investissement dans l''école et approfondissement du projet européen. Personnage fictif créé à des fins de démonstration.', 'https://example.org/candidats/camille-martin', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), true, 1) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:alexandre-leroy'), 'alexandre-leroy', 'Alexandre Leroy', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:party:alliance-nationale'), 'Ancien chef d''entreprise et parlementaire, Alexandre Leroy porte un programme axé sur la baisse des dépenses publiques, la fermeté migratoire et la souveraineté nationale. Personnage fictif créé à des fins de démonstration.', 'https://example.org/candidats/alexandre-leroy', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), true, 2) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:sarah-moreau'), 'sarah-moreau', 'Sarah Moreau', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:party:generation-verte'), 'Ingénieure devenue élue régionale, Sarah Moreau porte un projet écologiste : transition énergétique accélérée, justice fiscale et renforcement des services publics. Personnage fictif créé à des fins de démonstration.', 'https://example.org/candidats/sarah-moreau', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), true, 3) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:thomas-bernard'), 'thomas-bernard', 'Thomas Bernard', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:party:union-populaire-demo'), 'Ancien syndicaliste et député, Thomas Bernard défend une ligne sociale : hausse des salaires, retour de la retraite à 60 ans et renforcement des services publics. Personnage fictif créé à des fins de démonstration.', 'https://example.org/candidats/thomas-bernard', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), true, 4) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nina-laurent'), 'nina-laurent', 'Nina Laurent', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:party:horizon-liberal'), 'Entrepreneuse et économiste, Nina Laurent promeut une ligne libérale : baisse des charges, simplification administrative et attractivité économique de la France. Personnage fictif créé à des fins de démonstration.', 'https://example.org/candidats/nina-laurent', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), true, 5) on conflict (id) do nothing;
